<?php
function masterView(string $module): void {
    $s=masters()[$module];$edit=isset($_GET['edit'])?one("SELECT * FROM {$s['table']} WHERE {$s['pk']}=?",[integer($_GET['edit'])]):null;
    heading('WORKSPACE RECORDS',$s['title'],'Keep your records clear, current, and easy to find.');
    echo '<div class="manage-layout"><section class="panel"><div class="panel-head"><h2>'.($edit?'Edit record':'Add a record').'</h2>'.($edit?'<a class="text-link" href="?page='.h($module).'">Cancel</a>':'').'</div>';
    formStart('master_save',['module'=>$module,'id'=>$edit[$s['pk']]??0]);
    foreach($s['fields'] as $name=>$f){$value=$edit[$name]??($f[0]==='check'?1:'');
        switch($f[0]){
        case 'select':case 'optional':$opts=options($f[2],$f[3],$f[4],$name==='refill_menu_item_id'?"item_type='rice' AND is_active=1":'1=1');if($module==='users'&&$name==='role_id'&&(!$edit||(int)$edit['role_id']!==1))unset($opts[1]);selectField($f[1],$name,$opts,$value,$f[0]==='optional');break;
        case 'enum':selectField($f[1],$name,$f[2],$value);break;
        case 'check':echo '<label class="check full"><input type="checkbox" name="'.h($name).'" '.($value?'checked':'').'>'.h($f[1]).'</label>';break;
        case 'money':case 'quantity':field($f[1],$name,'number',$value===''?0:$value,'min="0" max="9999999" step="'.($f[0]==='money'?'0.01':'0.001').'" required');break;
        case 'password':field($f[1],$name,'password','','minlength="10" maxlength="72" autocomplete="new-password" '.($edit?'':'required'));break;
        default:field($f[1],$name,'text',$value,'maxlength="'.$f[2].'" '.($f[0]==='optionaltext'?'':'required'));
        }
    }formEnd($edit?'Update record':'Create record');
    if($module==='catalog')echo '<p class="hint">Unli meals include initial rice. Configure a combo’s components in Combo builder before offering it.</p>';
    if($module==='ingredients')echo '<p class="hint">Use one base unit per ingredient. Opening balances are recorded in Stock movements.</p>';
    echo '</section><section class="panel">';filterBar('Search '.strtolower($s['title']).'…');$records=rows("SELECT * FROM {$s['table']} ORDER BY {$s['pk']} DESC");$data=[];$headers=['ID'];$shown=array_filter($s['fields'],fn($f)=>!in_array($f[0],['password'])&&$f[1]!=='Address');foreach($shown as $f)$headers[]=$f[1];$headers[]='Actions';
    foreach($records as $r){if(!matches(implode(' ',array_intersect_key($r,$s['fields']))))continue;$line=[h($r[$s['pk']])];foreach($shown as $name=>$f){$v=$r[$name]??'';if(in_array($f[0],['select','optional']))$v=$v?val("SELECT {$f[4]} FROM {$f[2]} WHERE {$f[3]}=?",[$v]):'—';$line[]=$f[0]==='check'?badge($v?'Yes':'No',$v?'green':''):($f[0]==='money'?money($v):h($v));}$line[]='<a class="btn ghost small" href="?page='.h($module).'&edit='.$r[$s['pk']].'">Edit</a>'.($module!=='users'?buttonForm('master_delete',['module'=>$module,'id'=>$r[$s['pk']]],'Delete','Delete this unused record? Linked records cannot be deleted.','danger small'):'');$data[]=$line;}
    tableView($headers,$data);echo '<p class="hint table-note">Deactivate used records to preserve history. Only unused records can be deleted.</p></section></div>';
}
function dailyView(): void {
    $d=isset($_GET['edit'])?one('SELECT * FROM daily_menu_items WHERE daily_menu_item_id=? AND menu_date=?',[integer($_GET['edit']),today()]):null;
    heading('PREPARED WITH CARE','Today’s menu','Choose today’s dishes, set portions, and keep the counter up to date.',badge(date('F j, Y'),'green'));
    echo '<div class="manage-layout"><section class="panel"><div class="panel-head"><h2>'.($d?'Update today’s listing':'Add to today’s menu').'</h2></div>';formStart('daily_save');
    selectField('Dish, drink or combo','menu_item_id',options('menu_items','menu_item_id','name','is_active=1'),$d['menu_item_id']??'');
    if(owner())field('Today’s selling price','selling_price','number',$d['selling_price']??'','min="0" max="9999999" step="0.01" required');
    field('Total portions prepared','prepared_qty','number',$d['prepared_qty']??0,'min="0" max="100000" step="1" required');field('Total portions wasted','wasted_qty','number',$d['wasted_qty']??0,'min="0" max="100000" step="1" required');
    field('Reason / preparation note','reason','text','Daily preparation','required maxlength="255"');echo '<label class="check full"><input name="is_enabled" type="checkbox" '.(!$d||$d['is_enabled']?'checked':'').'>Available at the counter</label>';formEnd('Save today’s listing');echo '<p class="hint">Enter cumulative totals for today, not just the latest batch. Combos use component stock, so their prepared and wasted fields are ignored. Staff listings use the standard catalog price.</p></section><section class="panel">';filterBar('Search today’s menu…');$data=[];
    foreach(menu(today())as $m)if(matches($m['name'].' '.$m['category']))$data[]=['<span class="dish-label">'.foodEmoji($m['name']).' '.h($m['name']).'</span>',money($m['selling_price']),$m['prepared_qty']===null?'Components':h($m['prepared_qty']),h($m['served']),h($m['wasted_qty']),'<b>'.$m['remaining'].'</b>',badge($m['available']?'Available':'Unavailable',$m['available']?'green':'amber'),'<a class="btn ghost small" href="?page=daily-menu&edit='.$m['daily_menu_item_id'].'">Edit</a>'.(owner()?buttonForm('daily_delete',['id'=>$m['daily_menu_item_id']],'Remove','Remove this unused daily listing?','danger small'):'')];
    tableView(['Item','Price','Prepared','Served','Waste','Left','Status','Actions'],$data,'Add your first dish to open today’s menu.');echo '</section></div>';
}
function combosView(): void {
    heading('BETTER TOGETHER','Combo builder','Build fixed meals from dishes, rice, and drinks.');echo '<div class="manage-layout"><section class="panel"><div class="panel-head"><h2>Add or update a component</h2></div>';formStart('combo_add');selectField('Combo offer','combo_menu_item_id',options('menu_items','menu_item_id','name',"item_type='combo' AND is_active=1"));selectField('Included product','component_menu_item_id',options('menu_items','menu_item_id','name',"item_type<>'combo' AND is_active=1"));field('Portions per combo','quantity','number',1,'min="1" max="100" required');formEnd('Save component');echo '<p class="hint">Adding an existing component replaces its quantity. Unli-rice combos must include their configured rice. Changes affect future sales only.</p></section><section class="panel">';$data=[];foreach(rows('SELECT c.*,p.name combo,m.name component FROM combo_components c JOIN menu_items p ON p.menu_item_id=c.combo_menu_item_id JOIN menu_items m ON m.menu_item_id=c.component_menu_item_id ORDER BY p.name,m.name')as $r)$data[]=[h($r['combo']),h($r['component']),h($r['quantity']),buttonForm('combo_delete',['id'=>$r['combo_component_id']],'Remove','Remove this component from future combos?','danger small')];tableView(['Combo','Component','Portions','Action'],$data);echo '</section></div>';
}
function inventoryView(): void {
    heading('KNOW WHAT’S IN THE KITCHEN','Ingredient stock','Raw ingredients and supplies, measured in consistent base units.','<a class="btn primary" href="?page=movements">'.icon('plus').' Record movement</a>');filterBar('Find an ingredient…');$r=rows('SELECT i.*,u.symbol,COALESCE(m.balance,0) balance FROM inventory_items i JOIN units u ON u.unit_id=i.unit_id LEFT JOIN (SELECT inventory_item_id,SUM(quantity_change) balance FROM stock_movements GROUP BY inventory_item_id) m ON m.inventory_item_id=i.inventory_item_id ORDER BY i.name');$data=[];
    foreach($r as $i)if(matches($i['name']))$data[]=['<strong>'.h($i['name']).'</strong>',h($i['balance'].' '.$i['symbol']),h($i['reorder_level'].' '.$i['symbol']),badge(!$i['is_active']?'Inactive':($i['balance']<=$i['reorder_level']?'Reorder soon':'Healthy'),!$i['is_active']?'':($i['balance']<=$i['reorder_level']?'amber':'green'))];echo '<section class="panel">';tableView(['Ingredient','On hand','Reorder level','Status'],$data);echo '</section><p class="hint">Raw stock changes when supplies arrive or ingredients are issued to the kitchen. Sales deduct prepared portions separately.</p>';
}
function movementsView(): void {
    heading('EVERY INGREDIENT COUNTS','Stock movements','Record kitchen usage, wastage, and traceable stock corrections.');echo '<div class="manage-layout"><section class="panel"><div class="panel-head"><h2>Record a movement</h2></div>';formStart('stock_move',['operation_token'=>token()]);selectField('Ingredient','inventory_item_id',options('inventory_items','inventory_item_id','name','is_active=1'));$types=['kitchen_issue'=>'Issue to kitchen','wastage'=>'Ingredient wastage'];if(owner())$types=['opening_balance'=>'Opening balance',...$types,'adjustment'=>'Stock adjustment'];selectField('Movement type','movement_type',$types);field('Quantity in base units','quantity','number','','step="0.001" min="0.001" max="9999999" required');if(owner())selectField('Adjustment direction only','direction',['in'=>'Add stock','out'=>'Remove stock'],'in');field('Reason','reason','text','','required maxlength="255"');formEnd('Record movement');echo '<p class="hint">Use an adjustment to correct a count. Historical movements cannot be edited or deleted.</p></section><section class="panel">';filterBar('Search ingredient, type, or reason…');$data=[];foreach(rows('SELECT m.*,i.name,u.symbol,a.full_name FROM stock_movements m JOIN inventory_items i ON i.inventory_item_id=m.inventory_item_id JOIN units u ON u.unit_id=i.unit_id JOIN users a ON a.user_id=m.recorded_by ORDER BY movement_id DESC')as $m)if(matches($m['name'].' '.$m['movement_type'].' '.$m['reason']))$data[]=[h($m['recorded_at']),h($m['name']),badge(str_replace('_',' ',$m['movement_type'])),'<b class="'.($m['quantity_change']>0?'positive':'negative').'">'.($m['quantity_change']>0?'+':'').h($m['quantity_change'].' '.$m['symbol']).'</b>',h($m['reason']),h($m['full_name'])];tableView(['Time','Ingredient','Type','Change','Reason','Recorded by'],$data);echo '</section></div>';
}
function receivingView(): void {
    heading('FRESH SUPPLIES','Stock receiving','Build a receipt, check its lines, and post it once to update stock.');echo '<div class="manage-layout"><section class="panel"><div class="panel-head"><h2>Start a receipt</h2></div>';formStart('receipt_create',['operation_token'=>token()]);selectField('Supplier','supplier_id',options('suppliers','supplier_id','name','is_active=1'));field('Vendor reference (optional)','reference_number','text','','maxlength="50"');selectField('Paid from','payment_source',['owner'=>'Owner’s separate cash','drawer'=>'Cash drawer'],'owner');formEnd('Create draft receipt');echo '<p class="hint">Drafts do not affect cash or inventory. Post only after the supplies have arrived and payment is complete.</p></section><section class="panel">';filterBar('Find supplier or reference…');$data=[];foreach(rows('SELECT r.*,s.name,COALESCE(t.total,0) total FROM stock_receipts r JOIN suppliers s ON s.supplier_id=r.supplier_id LEFT JOIN (SELECT stock_receipt_id,SUM(ROUND(quantity*unit_cost,2)) total FROM stock_receipt_items GROUP BY stock_receipt_id) t ON t.stock_receipt_id=r.stock_receipt_id ORDER BY r.stock_receipt_id DESC')as $r)if(matches($r['name'].' '.$r['reference_number'].' '.$r['stock_receipt_id']))$data[]=['<a class="text-link" href="?page=receipt&id='.$r['stock_receipt_id'].'">Receipt #'.$r['stock_receipt_id'].'</a>',h($r['name']),h($r['received_at']),money($r['total']),badge($r['status'],$r['status']==='posted'?'green':'amber'),h($r['payment_source'])];tableView(['Receipt','Supplier','Received','Total','Status','Paid from'],$data);echo '</section></div>';
}
function receiptView(): void {
    $id=integer($_GET['id']??0);$r=one('SELECT r.*,s.name FROM stock_receipts r JOIN suppliers s ON s.supplier_id=r.supplier_id WHERE stock_receipt_id=?',[$id]);if(!$r)throw new RuntimeException('Receipt not found.');heading('STOCK RECEIPT','Receipt #'.$id,$r['name'].' · '.$r['payment_source'].' payment · '.($r['reference_number']?:'No vendor reference'),badge($r['status'],$r['status']==='posted'?'green':'amber'));
    echo '<div class="manage-layout">';if($r['status']==='draft'){echo '<section class="panel"><div class="panel-head"><h2>Add or replace a line</h2></div>';formStart('receipt_line',['id'=>$id]);selectField('Ingredient','inventory_item_id',options('inventory_items','inventory_item_id','name','is_active=1'));field('Quantity in base units','quantity','number','','min="0.001" step="0.001" max="9999999" required');field('Cost per base unit','unit_cost','number','','min="0" step="0.01" max="9999999" required');formEnd('Save receipt line');echo '<p class="hint">Adding the same ingredient replaces its quantity and cost. All amounts are in pesos.</p></section>';}
    echo '<section class="panel"><div class="panel-head"><h2>Purchased ingredients</h2></div>';$data=[];$total=0;foreach(rows('SELECT l.*,i.name,u.symbol FROM stock_receipt_items l JOIN inventory_items i ON i.inventory_item_id=l.inventory_item_id JOIN units u ON u.unit_id=i.unit_id WHERE stock_receipt_id=?',[$id])as $l){$amount=intdiv(fixed($l['quantity'])*cents($l['unit_cost'])+500,1000);$total+=$amount;$line=[h($l['name']),h($l['quantity'].' '.$l['symbol']),money($l['unit_cost']),money(dec($amount))];if($r['status']==='draft')$line[]=buttonForm('receipt_line_delete',['id'=>$id,'line_id'=>$l['stock_receipt_item_id']],'Remove','Remove this draft line?','danger small');$data[]=$line;}$headers=['Ingredient','Quantity','Unit cost','Amount'];if($r['status']==='draft')$headers[]='Action';tableView($headers,$data,'Add the ingredients received.',false);echo '<div class="total-row">Receipt total <strong>'.money(dec($total)).'</strong></div>';if($r['status']==='draft')echo '<div class="form-actions">'.buttonForm('receipt_post',['id'=>$id],'Post receipt','Post this receipt? It will update inventory and cash and cannot be edited.','primary').buttonForm('receipt_delete',['id'=>$id],'Delete draft','Delete this draft and its lines?','danger').'</div>';else echo '<p class="notice">Posted '.h($r['posted_at']).'. Ingredient stock has been updated.</p>';echo '</section></div>';
}
function expensesView(): void {
    heading('KEEP THE SMALL COSTS CLEAR','Operating expenses','Record payments for running the carinderia. Purchases belong in Stock receiving.');echo '<div class="manage-layout"><section class="panel"><div class="panel-head"><h2>Record a paid expense</h2></div>';formStart('expense_add',['operation_token'=>token()]);selectField('Category','expense_category_id',options('expense_categories','expense_category_id','name','is_active=1'));field('Amount paid','amount','number','','min="0.01" step="0.01" max="9999999" required');field('Description','description','text','','required maxlength="255"');selectField('Paid from','payment_source',['owner'=>'Owner’s separate cash','drawer'=>'Cash drawer'],'owner');echo '<p class="hint full">This is a final payment record. Check the amount and category before saving.</p>';formEnd('Record expense');echo '</section><section class="panel">';filterBar('Search expense or category…',true);$from=dateval($_GET['from']??today());$to=dateval($_GET['to']??today());$data=[];foreach(rows('SELECT e.*,c.name FROM expenses e JOIN expense_categories c ON c.expense_category_id=e.expense_category_id WHERE paid_at BETWEEN ? AND ? ORDER BY expense_id DESC',[$from,$to.' 23:59:59'])as $e)if(matches($e['name'].' '.$e['description']))$data[]=[h($e['paid_at']),h($e['name']),h($e['description']),money($e['amount']),badge($e['payment_source'])];tableView(['Paid at','Category','Description','Amount','Source'],$data);echo '</section></div>';
}
function cashView(): void {
    heading('A CLEAR START AND FINISH','Cash drawer','One drawer, one accountable cashier, and an honest end-of-day count.');$s=openSession(false);
    if(!$s){echo '<section class="panel narrow"><div class="panel-head"><h2>Open your cash session</h2></div>';formStart('session_open');field('Opening cash float','opening_float','number','0.00','min="0" max="9999999" step="0.01" required');formEnd('Open drawer');echo '</section>';}else{
        $t=sessionTotals((int)$s['cash_session_id']);echo '<div class="notice">Drawer open · '.h($s['full_name']).' · since '.h($s['opened_at']).'</div><div class="metrics">';metric('Opening float',money($s['opening_float']),'Starting cash','cash');metric('Cash sales',money(dec($t['sales'])),'Net payments retained','bag');metric('Cash paid out',money(dec($t['purchases']+$t['expenses'])),'Purchases + operating expenses','receipt');metric('Expected in drawer',money(dec($t['expected'])),'Before physical count','cash');echo '</div>';
        if((int)$s['user_id']===(int)need()['user_id']){echo '<section class="panel narrow"><div class="panel-head"><h2>Count and close</h2></div>';formStart('session_close',['id'=>$s['cash_session_id']]);field('Cash physically counted','counted_cash','number','','min="0" max="9999999" step="0.01" required');echo '<p class="hint full">Count the actual cash. The difference is recorded even when it does not match the expected balance.</p><div class="form-actions full"><button class="btn primary" data-confirm="Close the drawer? No more sales or cash payments can use this session.">Close cash session</button></div></form></section>';}
    }
    echo '<section class="panel"><div class="panel-head"><h2>Session history</h2></div>';$args=[];$where='';if(!owner()){$where=' WHERE c.user_id=?';$args[] =need()['user_id'];}$data=[];foreach(rows('SELECT c.*,u.full_name FROM cash_sessions c JOIN users u ON u.user_id=c.user_id'.$where.' ORDER BY cash_session_id DESC',$args)as $r){$t=sessionTotals((int)$r['cash_session_id']);$diff=$r['counted_cash']===null?null:cents($r['counted_cash'])-$t['expected'];$data[]=['#'.$r['cash_session_id'],h($r['full_name']),h($r['opened_at']),h($r['closed_at']??'—'),money(dec($t['expected'])),$r['counted_cash']===null?'—':money($r['counted_cash']),$diff===null?'—':'<b class="'.($diff===0?'positive':'negative').'">'.money(dec($diff)).'</b>',badge($r['status'],$r['status']==='open'?'green':'')];}tableView(['Session','Cashier','Opened','Closed','Expected','Counted','Variance','Status'],$data);echo '</section>';
}
